<script setup lang="ts">
import { ref, computed, onMounted, onBeforeUnmount } from 'vue';
import type { AccountView, Entity, Person, VaultDescriptor, FollowUp, DirectoryEntry } from '@zhijiao/shared';
import { IndexedDbStore, planPersonDeletion } from '@zhijiao/client';
import { auth, ApiError } from './auth'; import { client, connectVault, disconnectVault, lockVault, vaultState, entities, directory, base, saveEntities, generation, isCurrent } from './state';
import { label, sortedInteractions, titleOf, isOverdue } from './format';
import ValidatedForm from './components/ValidatedForm.vue'; import FormField from './components/FormField.vue'; import FormNotice from './components/FormNotice.vue';
import { loginRule, loginPasswordRule, passphraseRule, secretRule, matches } from './validation';
import Icon from './components/Icon.vue'; import Avatar from './components/Avatar.vue'; import Drawer from './components/Drawer.vue'; import EntityEditor from './components/EntityEditor.vue'; import QuickJournal from './components/QuickJournal.vue'; import PersonDetail from './components/PersonDetail.vue'; import RecordCard from './components/RecordCard.vue'; import RecordDetails from './components/RecordDetails.vue'; import HistoryPanel from './components/HistoryPanel.vue'; import AvatarEditor from './components/AvatarEditor.vue'; import SettingsPage from './components/SettingsPage.vue'; import BackupRestore from './components/BackupRestore.vue';
type Page = 'home' | 'people' | 'interactions' | 'tasks' | 'settings'; type EditableKind = 'person' | 'contact' | 'fact' | 'interaction' | 'reflection' | 'followUp' | 'tag';
const account = ref<AccountView>(); const booting = ref(true); const offline = ref(false); const online = ref(navigator.onLine); const vaults = ref<VaultDescriptor[]>([]); const localVaults = ref<VaultDescriptor[]>([]); const chosenVault = ref(''); const busy = ref(false); const saving = ref(false); const error = ref(''); const toast = ref('');
const login = ref(''); const password = ref(''); const unlockSecret = ref(''); const unlockRecovery = ref(false); const setupPassphrase = ref(''); const setupRepeated = ref(''); const recoverySecret = ref(''); const recoveryReason = ref<'setup' | 'rotation'>('setup'); const rotationComplete = ref(true); const recoverySaved = ref(false); const restoreOpen = ref(false);
const page = ref<Page>('home'); const selectedPerson = ref(''); const search = ref(''); const showArchived = ref(false); const taskFilter = ref('pending');
const editor = ref<{ kind: EditableKind; entity?: Entity; personId?: string }>(); const journal = ref<{ personId?: string }>(); const detail = ref<Entity>(); const history = ref<Entity>(); const avatarPersonId = ref(''); const deletion = ref<Entity>(); const tagManager = ref(false); let toastTimer: ReturnType<typeof setTimeout> | undefined;
const unlocked = computed(() => !!client.value && !vaultState.value?.locked && !recoverySecret.value);
const person = computed(() => entities.value.find((record): record is Person => record.kind === 'person' && record.id === selectedPerson.value));
const recent = computed(() => sortedInteractions(entities.value)); const tasks = computed(() => entities.value.filter((record): record is FollowUp => record.kind === 'followUp').sort((a,b) => (a.dueAt ?? a.dueDate ?? '9999').localeCompare(b.dueAt ?? b.dueDate ?? '9999')));
const pendingTasks = computed(() => tasks.value.filter(task => task.status === 'pending')); const filteredTasks = computed(() => tasks.value.filter(task => taskFilter.value === 'all' || task.status === taskFilter.value));
const filteredPeople = computed(() => { const entries = directory.value.filter(entry => showArchived.value || entry.status === 'active'); if (!search.value.trim()) return entries.sort((a,b) => b.updatedAt.localeCompare(a.updatedAt)); const ids = new Set(client.value?.searchPeople(search.value, { includeArchived: showArchived.value }).entries.map(entry => entry.personId)); return entries.filter(entry => ids.has(entry.personId) || showArchived.value && [entry.displayName,...entry.aliases].some(name => name.toLowerCase().includes(search.value.toLowerCase()))); });
const searchMatches = computed(() => { void directory.value; return search.value.trim() ? client.value?.searchPeople(search.value).entries.slice(0, 8) ?? [] : []; });
const searchedInteractions = computed(() => recent.value.filter(record => !search.value.trim() || `${record.title} ${record.content} ${record.occurredOn ?? ''} ${record.occurredAt ?? ''} ${record.participantIds.map(id => directory.value.find(entry => entry.personId === id)?.displayName ?? '').join(' ')}`.toLowerCase().includes(search.value.trim().toLowerCase())));
const deletePlan = computed(() => deletion.value?.kind === 'person' ? planPersonDeletion(deletion.value.id, entities.value) : undefined);
const syncText = computed(() => offline.value ? '本机缓存模式' : !online.value ? '离线 · 本机加密保存' : vaultState.value?.syncing ? '正在同步' : vaultState.value?.conflicts ? `${vaultState.value.conflicts} 个冲突待处理` : vaultState.value?.lastError ? '云端同步暂未完成' : vaultState.value?.pending ? `${vaultState.value.pending} 项待同步` : '已同步当前快照');
const navigation: Array<{ id: Page; title: string; icon: string }> = [{id:'home',title:'首页',icon:'home'},{id:'people',title:'人物',icon:'people'},{id:'interactions',title:'交往',icon:'journal'},{id:'tasks',title:'事项',icon:'tasks'},{id:'settings',title:'设置',icon:'settings'}];
function notify(message: string) { toast.value = message; clearTimeout(toastTimer); toastTimer = setTimeout(() => { toast.value = ''; }, 4500); }
function clearPlainUi() { editor.value = undefined; journal.value = undefined; detail.value = undefined; history.value = undefined; avatarPersonId.value = ''; deletion.value = undefined; tagManager.value = false; selectedPerson.value = ''; search.value = ''; unlockSecret.value = ''; setupPassphrase.value = ''; setupRepeated.value = ''; recoverySecret.value = ''; recoverySaved.value = false; error.value = ''; toast.value = ''; saving.value = false; }
function lock() { lockVault(); clearPlainUi(); page.value = 'home'; }
function navigate(next: Page) { page.value = next; selectedPerson.value = ''; search.value = ''; window.history.pushState({ page: next }, '', `#${next}`); }
function openPerson(entry: DirectoryEntry) { if (!entities.value.some(record => record.id === entry.personId && record.kind === 'person')) { notify('人物目录已下载，完整资料仍在同步。请稍后查看。'); return; } selectedPerson.value = entry.personId; page.value = 'people'; search.value = ''; client.value?.markPersonUsed(entry.personId); window.history.pushState({ page: 'people', personId: entry.personId }, '', `#people/${entry.personId}`); }
function openRecord(record: Entity) { detail.value = record; }
function editRecord(record: Entity) { if (!['person','contact','fact','interaction','reflection','followUp','tag'].includes(record.kind)) return; error.value = ''; detail.value = undefined; tagManager.value = false; editor.value = { kind: record.kind as EditableKind, entity: record }; }
function addRecord(kind: EditableKind, personId?: string) { error.value = ''; editor.value = { kind, personId }; }
function startJournal(personId?: string) { error.value = ''; journal.value = { personId }; }
async function readLocalVaults() { localVaults.value = await new IndexedDbStore().listVaults(); }
async function openOnlineVaults() { vaults.value = await auth.vaults(); const engine = connectVault(account.value!.id); chosenVault.value = vaults.value[0]?.id ?? ''; if (chosenVault.value) await engine.open(chosenVault.value); }
async function signIn() { if (busy.value) return; busy.value = true; error.value = ''; try { account.value = await auth.login(login.value.trim(), password.value); offline.value = false; await openOnlineVaults(); } catch (failure) { error.value = failure instanceof ApiError ? failure.message : '暂时无法连接服务，请检查网络与服务状态。'; } finally { password.value = ''; busy.value = false; } }
async function signOut() { lock(); busy.value = true; try { if (account.value) await auth.logout(); } catch { /* Locked local data remains protected if the network is unavailable. */ } account.value = undefined; offline.value = false; disconnectVault(); await readLocalVaults(); busy.value = false; }
async function chooseVault() { if (busy.value || !chosenVault.value) return; busy.value = true; error.value = ''; try { await client.value!.open(chosenVault.value); } catch { error.value = '资料库暂时无法读取，请检查登录会话与网络。'; } finally { busy.value = false; } }
async function retryVaultListing() { if (busy.value) return; busy.value = true; error.value = ''; try { await openOnlineVaults(); } catch { error.value = '资料库列表暂时无法读取，请检查网络后重试。'; } finally { busy.value = false; } }
async function openCached(id: string) { if (busy.value) return; busy.value = true; error.value = ''; try { const engine = connectVault(); await engine.openCached(id); chosenVault.value = id; offline.value = true; } catch { error.value = '该资料库的本机密文缓存无法读取。'; } finally { busy.value = false; } }
async function createVault() { if (busy.value) return; if (setupPassphrase.value.length < 12 || setupPassphrase.value !== setupRepeated.value) { error.value = '解锁口令至少 12 个字符，且两次输入须一致。'; return; } busy.value = true; error.value = ''; const token = generation; try { const result = await client.value!.setup(setupPassphrase.value); if (token !== generation) return; vaults.value = [result.vault]; chosenVault.value = result.vault.id; recoveryReason.value = 'setup'; recoverySecret.value = result.recoverySecret; recoverySaved.value = false; await readLocalVaults(); } catch { if (token === generation) error.value = '资料库创建未完成，请检查网络后重试。'; } finally { setupPassphrase.value = ''; setupRepeated.value = ''; if (token === generation) busy.value = false; } }
async function unlock() { if (busy.value) return; busy.value = true; error.value = ''; const token = generation; try { await client.value!.unlock(unlockSecret.value, { recovery: unlockRecovery.value }); if (token !== generation) return; page.value = 'home'; notify(offline.value ? '本机资料库已解锁。联网登录后才会同步。' : '资料库已解锁。'); } catch { if (token === generation) error.value = '无法解锁，请确认资料库口令或恢复秘密。登录密码不能代替解锁口令。'; } finally { unlockSecret.value = ''; if (token === generation) busy.value = false; } }
async function save(records: Entity[], remove: string[]) { if (saving.value) return; saving.value = true; const token = generation; try { await saveEntities(records, remove); if (!isCurrent(token)) return; for (const record of records) { if (record.kind === 'interaction') for (const id of record.participantIds) client.value!.markPersonUsed(id); } editor.value = undefined; journal.value = undefined; notify('已在本机加密保存。'); } catch { if (isCurrent(token)) error.value = '保存未完成。请检查必填内容或先处理同步冲突；表单内容已保留。'; } finally { if (isCurrent(token)) saving.value = false; } }
async function complete(record: Entity) { if (record.kind !== 'followUp' || saving.value) return; const updated: FollowUp = { ...record, ...base(record), status: record.status === 'completed' ? 'pending' : 'completed', completedAt: record.status === 'completed' ? undefined : new Date().toISOString() }; await save([updated], []); }
async function archive(record: Person) { await save([{...record, ...base(record), status: record.status === 'archived' ? 'active' : 'archived'}], []); }
async function removeConfirmed() { if (!deletion.value || saving.value) return; saving.value = true; const token = generation; const record = deletion.value; try { await client.value!.delete(record.id); if (!isCurrent(token)) return; deletion.value = undefined; detail.value = undefined; if (selectedPerson.value === record.id) selectedPerson.value = ''; notify('已保存删除标记，历史与备份仍按各自策略保留。'); } catch { if (isCurrent(token)) error.value = record.kind === 'person' && !vaultState.value?.recordsComplete ? '删除人物前需要完整同步正文，以保护其他参与者与事件。可先归档。' : '删除未完成，请同步并处理冲突后重试。'; } finally { if (isCurrent(token)) saving.value = false; } }
async function saveAvatar(file: File, crop: {x:number;y:number;size:number}) { if (saving.value) return; saving.value = true; const token = generation; try { const prepared = await client.value!.prepareAvatar(file, crop); if (!isCurrent(token)) return; await client.value!.putAvatar(avatarPersonId.value, prepared); if (!isCurrent(token)) return; avatarPersonId.value = ''; notify('头像已在本机处理并加密保存。'); } catch { if (isCurrent(token)) error.value = '头像保存未完成，请检查图片格式或先处理同步冲突。'; } finally { if (isCurrent(token)) saving.value = false; } }
function restoreBackup() { lock(); if (!client.value) connectVault(account.value?.id); if (!account.value) offline.value = true; restoreOpen.value = true; }
function showRotationRecovery(secret: string, completed: boolean) { recoveryReason.value = 'rotation'; rotationComplete.value = completed; recoverySecret.value = secret; recoverySaved.value = false; }
async function imported(vaultId: string) { restoreOpen.value = false; if (offline.value || !account.value) { await client.value!.openCached(vaultId); offline.value = true; } await readLocalVaults(); chosenVault.value = vaultId; notify('备份已导入本机。请输入对应口令或恢复秘密解锁。'); }
function pop(event: PopStateEvent) { if (!unlocked.value) return; const state = event.state as {page?:Page;personId?:string} | null; page.value = state?.page ?? 'home'; selectedPerson.value = state?.personId ?? ''; search.value = ''; editor.value = undefined; journal.value = undefined; detail.value = undefined; }
function connection() { online.value = navigator.onLine; if (online.value && unlocked.value && !offline.value) void client.value!.sync().catch(() => { /* Status retains the retryable sync error. */ }); }
onMounted(async () => { window.addEventListener('online', connection); window.addEventListener('offline', connection); window.addEventListener('popstate', pop); window.addEventListener('pagehide', lock); try { await readLocalVaults(); account.value = await auth.me(); await openOnlineVaults(); } catch { /* A login or explicit local-cache unlock is required. */ } booting.value = false; });
onBeforeUnmount(() => { window.removeEventListener('online', connection); window.removeEventListener('offline', connection); window.removeEventListener('popstate', pop); window.removeEventListener('pagehide', lock); clearTimeout(toastTimer); disconnectVault(); clearPlainUi(); });
</script>
<template><div v-if="booting" class="gate-page"><div class="brand gate-brand"><Icon name="leaf" :size="30" /><span>知交</span></div><p>正在打开你的私人笔记…</p></div><div v-else-if="!unlocked" class="gate-page"><div class="gate-art"><div class="brand"><Icon name="leaf" :size="34" /><span>知交</span></div><h1>让每次相处，<br>都有迹可循。</h1><p>记下交往，保留感受。<br>属于你的私人笔记，由你解锁。</p><div class="gate-decoration"><span /><span /><span /></div></div><main class="gate-card"><template v-if="recoverySecret"><p class="eyebrow">{{ recoveryReason === 'rotation' ? '数据密钥已更新 · 保存新恢复秘密' : '首次创建 · 最后一步' }}</p><h2>保存独立恢复秘密</h2><p>如果忘记解锁口令，这段秘密是恢复资料库的独立方式。只在这里显示一次，请保存到你信任的安全位置。</p><p v-if="recoveryReason === 'rotation'" class="notice">这是一段新的恢复秘密，请更新安全记录。旧恢复秘密不能解锁新密钥包，旧备份仍使用其原有口令或恢复秘密。</p><p v-if="recoveryReason === 'rotation' && !rotationComplete" class="error">新的密钥包已保存，重加密尚未完成。保存这段秘密后，请在设置中继续中断的密钥更换。</p><code class="recovery-secret">{{ recoverySecret }}</code><p class="notice">不要把恢复秘密与加密备份保存在同一处。管理员重置登录密码不能补发它。</p><label class="checkbox"><input v-model="recoverySaved" type="checkbox">我已安全保存，并理解丢失后的风险</label><button class="button primary full" :disabled="!recoverySaved" @click="recoverySecret = ''; recoverySaved = false">进入知交</button><button class="text-button block" @click="lock">先锁定</button></template><template v-else-if="client?.vault"><p class="eyebrow">{{ offline ? '本机缓存 · 离线解锁' : '已登录 · 资料库仍然锁定' }}</p><h2>打开你的资料库</h2><p class="muted">登录和解锁分别进行。资料库口令只在本机用于解密。</p><ValidatedForm id="unlock-form" :submit="unlock" :busy="busy">
<label v-if="vaults.length > 1 && !offline" class="field"><span>资料库</span><select v-model="chosenVault" :disabled="busy" @change="chooseVault"><option v-for="vault in vaults" :key="vault.id" :value="vault.id">资料库 {{ vault.id.slice(0,8) }}</option></select></label>
<FormField v-model="unlockSecret" name="unlockSecret" :label="unlockRecovery ? '独立恢复秘密' : '资料库解锁口令'" :rules="secretRule(unlockRecovery)" type="password" autocomplete="off" required :disabled="busy" />
<label class="checkbox"><input v-model="unlockRecovery" type="checkbox" :disabled="busy">使用恢复秘密解锁</label>
<button class="button primary full" :disabled="busy">{{ busy ? '正在本机解锁…' : '解锁资料库' }}</button></ValidatedForm><button class="text-button block" :disabled="busy" @click="restoreBackup">从加密备份恢复</button><button class="text-button block" :disabled="busy" @click="signOut">{{ offline ? '返回登录' : '退出登录' }}</button></template><template v-else-if="account && !client"><p class="eyebrow">已登录</p><h2>资料库列表暂时无法读取</h2><p class="muted">确认已有资料库后再继续，请连接服务重试。</p><button class="button primary full" :disabled="busy" @click="retryVaultListing">{{ busy ? '正在读取…' : '重新读取资料库' }}</button><button class="text-button block" :disabled="busy" @click="signOut">退出登录</button></template><template v-else-if="account && !vaults.length"><p class="eyebrow">第一次使用</p><h2>创建私人资料库</h2><p class="muted">设置独立解锁口令。请与登录密码区分，并准备安全保存恢复秘密。</p><ValidatedForm id="setup-form" :submit="createVault" :busy="busy">
<FormField v-model="setupPassphrase" name="setupPassphrase" label="解锁口令（至少 12 个字符）" :rules="passphraseRule" type="password" autocomplete="new-password" required :disabled="busy" />
<FormField v-model="setupRepeated" name="setupRepeated" label="再次输入" :rules="matches(() => setupPassphrase)" type="password" autocomplete="new-password" required :disabled="busy" />
<button class="button primary full" :disabled="busy">{{ busy ? '正在创建并包装密钥…' : '创建资料库' }}</button></ValidatedForm><button class="text-button block" :disabled="busy" @click="restoreBackup">已有加密备份？验证并恢复</button><button class="text-button block" :disabled="busy" @click="signOut">退出登录</button></template><template v-else><p class="eyebrow">欢迎回来</p><h2>登录知交</h2><p class="muted">先确认账号，再用独立口令解锁私人资料。</p><ValidatedForm id="login-form" :submit="signIn" :busy="busy">
<FormField v-model="login" name="login" label="登录名" :rules="loginRule" autocomplete="username" required :disabled="busy" />
<FormField v-model="password" name="password" label="登录密码" :rules="loginPasswordRule" type="password" autocomplete="current-password" required :disabled="busy" />
<button class="button primary full" :disabled="busy">{{ busy ? '正在登录…' : '登录' }}</button></ValidatedForm><p class="gate-help">账号由容器内交互命令管理，无公开注册或邮件找回。</p><details v-if="localVaults.length" class="form-details cached-entry"><summary>打开已缓存的本机资料库</summary><p class="muted">只能访问这台设备已有的密文，重新登录后才能同步。</p><button v-for="vault in localVaults" :key="vault.id" class="button secondary full" :disabled="busy" @click="openCached(vault.id)">本机资料库 · {{ vault.id.slice(0,8) }}</button></details><button class="text-button block" :disabled="busy" @click="restoreBackup">从加密备份恢复</button></template><FormNotice v-if="error" :message="error" /></main><p class="gate-footnote"><Icon name="lock" :size="14" />资料在本机加密，服务器保存密文。</p></div><div v-else class="app-shell"><aside class="sidebar"><a class="brand" href="#home" @click.prevent="navigate('home')"><Icon name="leaf" :size="29" /><span>知交</span></a><p class="sidebar-subtitle">记住相处的细节</p><nav aria-label="主要导航"><button v-for="item in navigation" :key="item.id" :class="{ active: page === item.id }" @click="navigate(item.id)"><Icon :name="item.icon" /><span>{{ item.title }}</span><small v-if="item.id === 'tasks' && pendingTasks.length">{{ pendingTasks.length }}</small></button></nav><div class="sidebar-bottom"><button class="sync-status" @click="navigate('settings')"><span class="status-dot" :class="{ warning: offline || !online || vaultState?.pending || vaultState?.conflicts || vaultState?.lastError }" />{{ syncText }}</button><button class="text-button" aria-label="锁定" @click="lock"><Icon name="lock" :size="16" />锁定资料库</button></div></aside><header class="mobile-header"><button class="brand" @click="navigate('home')"><Icon name="leaf" :size="24" /><span>知交</span></button><button class="icon-button" aria-label="锁定资料库" @click="lock"><Icon name="lock" /></button></header><main class="main-content"><div v-if="error" class="error global-error" role="alert">{{ error }}<button class="icon-button" aria-label="关闭提示" @click="error = ''"><Icon name="close" :size="16" /></button></div><p v-if="!vaultState?.directoryComplete" class="notice sync-notice">人物目录正在同步。搜索仅覆盖已下载人物；完整正文和头像会逐步加载。</p><p v-else-if="!vaultState?.recordsComplete" class="subtle-notice">人物目录已完整，交往正文仍在同步；搜索可查找全部人物。</p><PersonDetail v-if="person && page === 'people'" :person="person" @back="selectedPerson = ''" @edit="editRecord" @add="addRecord" @journal="startJournal" @avatar="avatarPersonId = $event" @archive="archive" @remove="deletion = $event" @history="history = $event" @open="openRecord" @complete="complete" /><template v-else-if="page === 'home'"><div class="page-heading"><div><p class="eyebrow">私人相处笔记</p><h1>留住值得记住的细节</h1><p class="muted">一次交往，一点感受，一件约定。</p></div><button class="button primary journal-cta" @click="startJournal()"><Icon name="plus" />记一笔</button></div><div class="home-search"><label class="search-input"><Icon name="search" /><input v-model="search" placeholder="找一个人，回顾最近的相处" aria-label="首页人物搜索"><small class="search-hint">姓名 / 昵称 / 拼音</small></label><div v-if="search.trim()" class="home-search-results"><button v-for="entry in searchMatches" :key="entry.personId" class="person-row" @click="openPerson(entry)"><Avatar :name="entry.displayName" :avatar="entry.avatar" /><span><strong>{{ entry.displayName }}</strong><small>{{ entry.distinguishing || '尚未填写辨识信息' }}</small></span><Icon name="arrow" :size="16" /></button><div v-if="!searchMatches.length" class="empty compact"><p>{{ vaultState?.directoryComplete ? '没有找到匹配的人物' : '已下载的目录中暂未找到，完整目录仍在同步' }}</p><button class="text-button" @click="addRecord('person')">新建人物</button></div></div></div><section class="home-metrics"><div><strong>{{ directory.filter(entry => entry.status === 'active').length }}</strong><span>位在来往的人</span></div><div><strong>{{ recent.length }}</strong><span>次交往被记住</span></div><div><strong>{{ pendingTasks.length }}</strong><span>件待办事项</span></div></section><div class="home-grid"><section><div class="section-title"><h2>近期交往</h2><button class="text-button" @click="navigate('interactions')">查看全部 <Icon name="arrow" :size="14" /></button></div><div class="record-list"><RecordCard v-for="record in recent.slice(0, 5)" :key="record.id" :record="record" :people="directory" @open="openRecord" @edit="editRecord" /></div><div v-if="!recent.length" class="empty panel"><div class="empty-icon"><Icon name="journal" :size="30" /></div><h3>从一件值得记住的事开始</h3><p>记下事件或感受，可以不关联人物。</p><button class="button primary" @click="startJournal()">记下第一笔</button></div></section><section><div class="section-title"><h2>待办与约定</h2><button class="text-button" @click="addRecord('followUp')"><Icon name="plus" :size="16" />添加</button></div><div class="record-list"><RecordCard v-for="record in pendingTasks.slice(0, 5)" :key="record.id" :record="record" :people="directory" @open="openRecord" @edit="editRecord" @complete="complete" /></div><div v-if="!pendingTasks.length" class="empty panel compact"><Icon name="tasks" :size="30" /><h3>暂时没有待办</h3><p>值得兑现的约定，可以和交往一起记下。</p></div><section class="home-note"><Icon name="leaf" :size="24" /><p>记住的是相处的细节，<br>也给新的理解留一点空间。</p></section></section></div></template><template v-else-if="page === 'people'"><div class="page-heading"><div><p class="eyebrow">在来往的人</p><h1>人物</h1></div><button class="button primary" @click="addRecord('person')"><Icon name="plus" :size="17" />新建人物</button></div><div class="list-toolbar"><label class="search-input"><Icon name="search" /><input v-model="search" placeholder="姓名、昵称、拼音或首字母" aria-label="搜索全部人物"></label><label class="checkbox"><input v-model="showArchived" type="checkbox">包含归档</label><button class="text-button" @click="tagManager = true">管理标签</button></div><p class="list-count">{{ filteredPeople.length }} 位人物{{ showArchived ? '（含归档）' : '' }}</p><div class="people-grid"><button v-for="entry in filteredPeople" :key="entry.personId" class="person-card" @click="openPerson(entry)"><Avatar :name="entry.displayName" :avatar="entry.avatar" /><div><h3>{{ entry.displayName }}</h3><p>{{ entry.distinguishing || '从一个称呼，慢慢记起这个人。' }}</p><small v-if="entry.status === 'archived'" class="badge">已归档</small></div><Icon name="arrow" :size="16" /></button></div><div v-if="!filteredPeople.length" class="empty"><Icon name="people" :size="38" /><h3>{{ search ? (vaultState?.directoryComplete ? '没有找到匹配人物' : '已下载的目录中暂未找到') : '先记下一个称呼' }}</h3><p>{{ !vaultState?.directoryComplete ? '目录尚未完整同步，当前结果不是全库结果。' : '其他信息可以在以后的相处中慢慢补充。' }}</p><button class="button secondary" @click="addRecord('person')">新建人物</button></div></template><template v-else-if="page === 'interactions'"><div class="page-heading"><div><p class="eyebrow">事件与感受 · 按日期回顾</p><h1>交往</h1></div><button class="button primary" @click="startJournal()"><Icon name="plus" :size="17" />记一笔</button></div><label class="search-input section-search"><Icon name="search" /><input v-model="search" aria-label="搜索交往" placeholder="搜索标题、内容、日期或关联人物"></label><div class="record-list wide"><RecordCard v-for="record in searchedInteractions" :key="record.id" :record="record" :people="directory" @open="openRecord" @edit="editRecord" /></div><div v-if="!searchedInteractions.length" class="empty"><Icon name="journal" :size="36" /><h3>{{ search ? '当前已下载的交往中没有匹配内容' : '还没有交往记录' }}</h3><p>事件或感受都可以直接记下，不必选择人物。</p></div></template><template v-else-if="page === 'tasks'"><div class="page-heading"><div><p class="eyebrow">记得兑现，也记得跟进</p><h1>事项</h1></div><button class="button primary" @click="addRecord('followUp')"><Icon name="plus" :size="17" />添加事项</button></div><div class="segmented task-filters"><button v-for="filter in ['pending','completed','cancelled','all']" :key="filter" :class="{ active: taskFilter === filter }" @click="taskFilter = filter">{{ filter === 'all' ? '全部' : label(filter) }}</button></div><p v-if="taskFilter === 'pending' && pendingTasks.some(isOverdue)" class="subtle-notice">{{ pendingTasks.filter(isOverdue).length }} 件事项已超过明确期限。</p><div class="record-list wide"><RecordCard v-for="record in filteredTasks" :key="record.id" :record="record" :people="directory" @open="openRecord" @edit="editRecord" @complete="complete" /></div><div v-if="!filteredTasks.length" class="empty"><Icon name="tasks" :size="36" /><h3>这里暂时没有事项</h3><p>约定或计划可与一次交往关联保存。</p></div></template><SettingsPage v-else :account="account" :offline="offline" @lock="lock" @logout="signOut" @restore="restoreBackup" @merge="editRecord" @history="history = $event" @recovery="showRotationRecovery" /></main><nav class="mobile-nav" aria-label="手机主要导航"><button v-for="item in navigation" :key="item.id" :class="{ active: page === item.id }" @click="navigate(item.id)"><Icon :name="item.icon" :size="21" /><span>{{ item.title }}</span></button></nav><QuickJournal v-if="journal" :person-id="journal.personId" :busy="saving" :failure="error" @save="save" @close="journal = undefined" /><EntityEditor v-if="editor" :kind="editor.kind" :entity="editor.entity" :person-id="editor.personId" :busy="saving" :failure="error" @save="save" @close="editor = undefined" /><RecordDetails v-if="detail" :record="detail" @close="detail = undefined" @edit="editRecord" @history="history = $event; detail = undefined" @remove="deletion = $event" @open="detail = $event" /><HistoryPanel v-if="history" :record="history" @close="history = undefined" @restored="history = undefined; notify('旧版本已恢复为新版本。')" /><AvatarEditor v-if="avatarPersonId" :busy="saving" :failure="error" @close="avatarPersonId = ''" @save="saveAvatar" /><Drawer v-if="tagManager" title="管理标签" subtitle="自由整理人物" @close="tagManager = false"><div class="record-list"><div v-for="tag in entities.filter(record => record.kind === 'tag')" :key="tag.id" class="session-row"><strong>{{ titleOf(tag) }}</strong><div><button class="text-button" @click="editRecord(tag)">重命名</button><button class="text-button danger" @click="deletion = tag">删除</button></div></div></div><p class="muted">在人物资料中选择标签，或添加新标签。</p><template #footer><button class="button primary" @click="tagManager = false; addRecord('tag')">新建标签</button></template></Drawer><Drawer v-if="deletion" :title="`删除${label(deletion.kind)}`" :busy="saving" @close="deletion = undefined"><p>确定删除“{{ titleOf(deletion).slice(0,100) }}”？</p><div v-if="deletePlan" class="notice"><p>删除人物和 {{ Math.max(0, deletePlan.deleteIds.length - 1) }} 条仅与此人物相关的当前记录；更新 {{ deletePlan.updates.length }} 条共享交往或事项，保留其他人物的参与关系。</p><p v-if="!vaultState?.recordsComplete">需先完整同步正文才能删除，当前可先归档。</p></div><p class="muted">删除以同步墓碑记录。历史版本、已下载的离线副本和过期前备份仍可能保留内容。</p><template #footer><button class="button secondary" :disabled="saving" @click="deletion = undefined">取消</button><button class="button destructive" :disabled="saving || deletion.kind === 'person' && !vaultState?.recordsComplete" @click="removeConfirmed">{{ saving ? '正在保存删除…' : '确认删除' }}</button></template></Drawer></div><BackupRestore v-if="restoreOpen" @close="restoreOpen = false" @imported="imported" /><Transition name="toast"><div v-if="toast" class="toast" role="status"><Icon name="check" :size="17" />{{ toast }}</div></Transition></template>
